def entregar_enteros_los_cortos(pedazos, codigo):
    """Un archivo corto (<= 600 renglones) se entrega ENTERO, una sola vez.

    Recibe pedazos (lista de dicts con pieza, abs, desde, hasta, texto) y
    codigo (lista de piezas con id y abs). Devuelve otra lista de pedazos.
    Si el archivo de un pedazo existe y tiene 600 renglones o menos, ese
    pedazo se sustituye por uno solo con el archivo ENTERO en texto,
    desde=1 y hasta=numero de renglones. Si el mismo archivo corto sale en
    varios pedazos, solo se entrega una vez. Si el archivo tiene mas de 600
    renglones o no se puede leer, el pedazo se deja tal cual. Nunca lanza:
    si algo falla, devuelve los pedazos como estaban.
    """
    LIMITE = 600
    try:
        if not pedazos:
            return pedazos

        abs_por_pieza = {}
        try:
            for pieza in codigo or []:
                if isinstance(pieza, dict):
                    pid = pieza.get("id")
                    pabs = pieza.get("abs")
                    if pid is not None and pabs:
                        abs_por_pieza[pid] = pabs
        except Exception:
            abs_por_pieza = {}

        salida = []
        ya_entregados = set()

        for pedazo in pedazos:
            try:
                if not isinstance(pedazo, dict):
                    salida.append(pedazo)
                    continue

                ruta = pedazo.get("abs")
                if not ruta:
                    ruta = abs_por_pieza.get(pedazo.get("pieza"))

                if not ruta:
                    salida.append(pedazo)
                    continue

                if ruta in ya_entregados:
                    continue

                try:
                    with open(ruta, "r", encoding="utf-8") as f:
                        lineas = f.readlines()
                except Exception:
                    salida.append(pedazo)
                    continue

                if len(lineas) > LIMITE:
                    salida.append(pedazo)
                    continue

                nuevo = dict(pedazo)
                nuevo["abs"] = ruta
                nuevo["desde"] = 1
                nuevo["hasta"] = len(lineas)
                nuevo["texto"] = "".join(lineas)
                salida.append(nuevo)
                ya_entregados.add(ruta)
            except Exception:
                salida.append(pedazo)

        return salida
    except Exception:
        return pedazos
